const { Client } = require('pg');

(async () => {
  const c = new Client({ connectionString: process.env.DATABASE_URL });
  await c.connect();
  await c.query('CREATE TABLE IF NOT EXISTS incidents (id serial primary key, title text, status text, created_at timestamptz default now())');
  await c.end();
})();

